  NURSE: ['patients:read','appointments:read','encounters:read','encounters:update','vitals:create','admissions:read','admissions:update','outpatient:read','wards:read','wards:update','nursing:read','nursing:create','nursing:update'],
  DERMATOLOGY: ['patients:read','appointments:read','appointments:update','encounters:read','encounters:create','encounters:update','lab:read','lab:create','prescriptions:read','prescriptions:create'],
