  LABORATORY: ['sms:read','sms:create','patients:read','lab:read','lab:create','lab:update'],
  RADIOLOGY: ['sms:read','sms:create','patients:read','radiology:read','radiology:update'],
  PHARMACY: ['patients:read','prescriptions:read','prescriptions:create','prescriptions:update','pharmacy:dispense','inventory:read','inventory:create','inventory:update','inventory:delete'],
  BILLING: ['patients:read','billing:read','billing:create','billing:update','reports:read'],
