app.disable('x-powered-by');
app.set('trust proxy', 1);
app.use((req, res, next) => {
  const requestId = req.get('x-request-id') || crypto.randomUUID();
  req.requestId = requestId;
  res.setHeader('x-request-id', requestId);
  res.setHeader('x-content-type-options', 'nosniff');
  res.setHeader('x-frame-options', 'DENY');
  res.setHeader('referrer-policy', 'no-referrer');
  if (IS_PROD) res.setHeader('strict-transport-security', 'max-age=31536000; includeSubDomains');
  next();
});
app.use(cors({ origin: CLIENT_ORIGIN, credentials: true, methods: ['GET','POST','PATCH','PUT','DELETE','OPTIONS'] }));
app.use(express.json({ limit: '4mb' }));
app.use(cookieParser());
app.use('/api', (_req, res, next) => { res.setHeader('cache-control', 'no-store, private'); next(); });

const loginAttempts = new Map();
function loginRateLimit(req, res, next) {
  const key = `${req.ip}:${String(req.body?.email || '').toLowerCase()}`;
  const now = Date.now();
  const recent = loginAttempts.get(key) || [];
  const active = recent.filter(t => now - t < 15 * 60 * 1000);
  if (active.length >= 10) return res.status(429).json({ message: 'Too many login attempts. Try again later.' });
  active.push(now); loginAttempts.set(key, active);
  next();
}

function signToken(user) {
  return jwt.sign({ sub: user.id, role: user.role }, JWT_SECRET, { expiresIn: '30m', issuer: 'easynet-solution' });
}
function setAuthCookie(res, token) {
  res.cookie('easynet_session', token, { httpOnly: true, sameSite: IS_PROD ? 'strict' : 'lax', secure: IS_PROD, maxAge: 30 * 60 * 1000, path: '/' });
}
function clearAuthCookie(res) {
  res.clearCookie('easynet_session', { httpOnly: true, sameSite: IS_PROD ? 'strict' : 'lax', secure: IS_PROD, path: '/' });
}
async function audit(req, action, entity, entityId, metadata = {}) {
  try {
    await prisma.auditLog.create({ data: { userId: req.user?.id, action, entity, entityId, ipAddress: req.ip, userAgent: req.get('user-agent')?.slice(0, 500), metadata } });
  } catch (error) { console.error('audit failure', error.message); }
}
async function requireAuth(req, res, next) {
  try {
    const token = req.cookies.easynet_session;
    if (!token) return res.status(401).json({ message: 'Authentication required' });
    const payload = jwt.verify(token, JWT_SECRET, { issuer: 'easynet-solution' });
    const user = await prisma.user.findUnique({ where: { id: payload.sub }, select: { id:true,email:true,firstName:true,lastName:true,role:true,isActive:true } });
    if (!user?.isActive) return res.status(401).json({ message: 'Account is inactive' });
    req.user = user;
    next();
  } catch { return res.status(401).json({ message: 'Invalid or expired session' }); }
}
function requirePermission(permission) {
  return (req, res, next) => {
    const allowed = ROLE_PERMISSIONS[req.user.role] || [];
    if (!allowed.includes('*') && !allowed.includes(permission)) return res.status(403).json({ message: 'Insufficient permissions' });
    next();
  };
}
async function nextNumber(tx, key, prefix, width = 6) {
  const sequence = await tx.sequence.upsert({ where: { key }, update: { value: { increment: 1 } }, create: { key, value: 1 } });
  return `${prefix}-${String(sequence.value).padStart(width, '0')}`;
}
const DEFAULT_FACILITY_TIMEZONE = 'Africa/Addis_Ababa';
function zoneParts(date, timeZone) {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone, year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', second:'2-digit', hourCycle:'h23' }).formatToParts(date);
  return Object.fromEntries(parts.filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));
}
function validTimeZone(timeZone) { try { new Intl.DateTimeFormat('en-US', { timeZone }).format(); return timeZone; } catch { return DEFAULT_FACILITY_TIMEZONE; } }
function zonedLocalToUtc(localIso, timeZone) {
  const safeZone = validTimeZone(timeZone);
  const base = new Date(`${localIso}Z`);
  let guess = base;
  for (let i=0;i<4;i++) {
    const p=zoneParts(guess,safeZone);
    const wall=Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute,p.second);
    const next=new Date(base.getTime()-(wall-guess.getTime()));
    if (next.getTime()===guess.getTime()) break;
    guess=next;
  }
  return guess;
}
function localDateString(date,timeZone) { const p=zoneParts(date,validTimeZone(timeZone)); return `${p.year}-${String(p.month).padStart(2,'0')}-${String(p.day).padStart(2,'0')}`; }
function addCalendarDay(dateOnly) { const d=new Date(`${dateOnly}T00:00:00Z`); d.setUTCDate(d.getUTCDate()+1); return d.toISOString().slice(0,10); }
function facilityRange(fromDate,toDate,timeZone) { const start=zonedLocalToUtc(`${fromDate}T00:00:00.000`,timeZone); const end=zonedLocalToUtc(`${addCalendarDay(toDate)}T00:00:00.000`,timeZone); return { gte:start, lt:end }; }
async function getFacilityTimezone(db=prisma) { const row=await db.systemSetting.findUnique({where:{singletonKey:'default'},select:{timezone:true}}); return validTimeZone(row?.timezone || process.env.FACILITY_TIMEZONE || DEFAULT_FACILITY_TIMEZONE); }
async function todayRange() { const tz=await getFacilityTimezone(); const day=localDateString(new Date(),tz); return { range:facilityRange(day,day,tz), timezone:tz, date:day }; }
async function assertActivePatient(db, patientId) { const patient=await db.patient.findUnique({where:{id:patientId},select:{id:true,status:true}}); if(!patient)return Object.assign(new Error('Patient not found'),{statusCode:404}); if(patient.status!=='ACTIVE')return Object.assign(new Error('Patient is not active'),{statusCode:409}); return patient; }
async function assertActiveDepartment(db, departmentId) { const department=await db.department.findUnique({where:{id:departmentId},select:{id:true,active:true}}); if(!department)return Object.assign(new Error('Department not found'),{statusCode:404}); if(!department.active)return Object.assign(new Error('Department is inactive'),{statusCode:409}); return department; }
const PROVIDER_ROLES=['PHYSICIAN','DERMATOLOGY','EMERGENCY','MATERNITY','SURGERY'];
const CLINICAL_ASSIGNEE_ROLES=[...PROVIDER_ROLES,'NURSE'];
async function assertActiveUser(db,userId,allowedRoles=CLINICAL_ASSIGNEE_ROLES) { const user=await db.user.findUnique({where:{id:userId},select:{id:true,isActive:true,role:true}}); if(!user)return Object.assign(new Error('User not found'),{statusCode:404}); if(!user.isActive)return Object.assign(new Error('User account is inactive'),{statusCode:409}); if(allowedRoles&&!allowedRoles.includes(user.role))return Object.assign(new Error('Selected user is not authorized for this clinical role'),{statusCode:403}); return user; }
async function assertActiveEncounterLink(db,encounterId,patientId,departmentId) { if(!encounterId)return null; const encounter=await db.encounter.findUnique({where:{id:encounterId},select:{id:true,patientId:true,departmentId:true,status:true,type:true}}); if(!encounter)return Object.assign(new Error('Encounter not found'),{statusCode:404}); if(encounter.patientId!==patientId)return Object.assign(new Error('Encounter does not belong to selected patient'),{statusCode:400}); if(departmentId && encounter.departmentId!==departmentId)return Object.assign(new Error('Encounter department does not match the order department'),{statusCode:400}); if(encounter.status==='CANCELLED')return Object.assign(new Error('Cancelled encounters cannot receive new clinical orders'),{statusCode:409}); return encounter; }

const id = z.string().cuid();
const loginSchema = z.object({ email:z.string().email().max(254), password:z.string().min(8).max(128) });
const patientSchema = z.object({ firstName:z.string().trim().min(1).max(80), middleName:z.string().trim().max(80).optional(), lastName:z.string().trim().min(1).max(80), dateOfBirth:z.string().datetime().optional(), sex:z.enum(['MALE','FEMALE','OTHER','UNKNOWN']).optional(), phone:z.string().trim().max(40).optional(), email:z.string().email().max(254).optional(), address:z.string().trim().max(500).optional(), nationalId:z.string().trim().max(80).optional(), emergencyName:z.string().trim().max(160).optional(), emergencyPhone:z.string().trim().max(40).optional(), bloodGroup:z.string().max(10).optional(), status:z.enum(['ACTIVE','INACTIVE','DECEASED']).optional(), departmentId:id.optional() });
const appointmentSchema = z.object({ patientId:id, departmentId:id, providerId:id.optional(), scheduledAt:z.string().datetime(), reason:z.string().max(500).optional(), notes:z.string().max(2000).optional() });
const encounterSchema = z.object({ patientId:id, departmentId:id, providerId:id.optional(), type:z.enum(['OPD','EMERGENCY','INPATIENT','MATERNITY','SURGERY','FOLLOW_UP','SPECIALTY']), chiefComplaint:z.string().max(2000).optional() });
const noteSchema = z.object({ noteType:z.string().trim().min(1).max(80), content:z.string().trim().min(1).max(10000) });
const diagnosisSchema = z.object({ code:z.string().max(30).optional(), description:z.string().trim().min(1).max(500), primary:z.boolean().optional() });
const vitalsSchema = z.object({ temperature:z.number().min(20).max(50).optional(), pulse:z.number().int().min(20).max(250).optional(), respiratoryRate:z.number().int().min(1).max(100).optional(), systolic:z.number().int().min(40).max(300).optional(), diastolic:z.number().int().min(20).max(200).optional(), oxygenSaturation:z.number().min(40).max(100).optional(), weight:z.number().positive().max(500).optional(), height:z.number().positive().max(300).optional() }).refine(v=>Object.values(v).some(x=>x!==undefined),{message:'At least one vital-sign measurement is required'});
const labOrderSchema = z.object({ patientId:id, departmentId:id, encounterId:id.optional(), testId:id.optional(), testName:z.string().min(1).max(150), priority:z.enum(['ROUTINE','URGENT','STAT']).default('ROUTINE'), specimen:z.string().max(100).optional(), notes:z.string().max(2000).optional() });
const labResultSchema = z.object({ testName:z.string().min(1).max(150), value:z.string().min(1).max(500), unit:z.string().max(50).optional(), reference:z.string().max(150).optional(), notes:z.string().max(2000).optional() });
const radiologySchema = z.object({ patientId:id, departmentId:id, encounterId:id.optional(), modality:z.string().min(1).max(60), studyName:z.string().min(1).max(150), priority:z.enum(['ROUTINE','URGENT','STAT']).default('ROUTINE'), clinicalIndication:z.string().max(2000).optional() });
const prescriptionSchema = z.object({ patientId:id, medicationId:id, encounterId:id.optional(), dose:z.string().min(1).max(100), frequency:z.string().min(1).max(100), duration:z.string().min(1).max(100), quantity:z.number().int().positive().max(100000), instructions:z.string().max(1000).optional() });
const insuranceProviderSchema = z.object({ code:z.string().trim().min(2).max(30), name:z.string().trim().min(2).max(160), phone:z.string().max(40).optional(), email:z.string().email().max(254).optional(), address:z.string().max(500).optional(), scheme:z.enum(['CBHI','SHI','PRIVATE','EMPLOYER','OTHER']).default('OTHER') });
const insurancePolicySchema = z.object({ patientId:id, providerId:id, policyNumber:z.string().trim().min(2).max(80), memberNumber:z.string().trim().max(80).optional(), validFrom:z.string().datetime().optional(), validTo:z.string().datetime().optional(), active:z.boolean().optional(), coverageLimit:z.number().nonnegative().optional(), deductiblePercent:z.number().min(0).max(100).optional(), benefitPackage:z.string().max(160).optional() });
const preauthSchema = z.object({ patientId:id, policyId:id, providerId:id, encounterId:id.optional(), requestedAmount:z.number().positive(), serviceDescription:z.string().trim().min(3).max(2000), diagnosisCode:z.string().max(40).optional(), procedureCode:z.string().max(40).optional() });
const userSchema = z.object({ email:z.string().email().max(254), firstName:z.string().trim().min(1).max(80), lastName:z.string().trim().min(1).max(80), role:z.enum(['SYSTEM_ADMINISTRATOR','RECEPTIONIST','PHYSICIAN','NURSE','DERMATOLOGY','PATHOLOGY','LABORATORY','RADIOLOGY','PHARMACY','BILLING','INSURANCE','MEDICAL_RECORDS','INVENTORY','MATERNITY','SURGERY','EMERGENCY','BLOOD_BANK']), password:z.string().min(12).max(128).optional(), isActive:z.boolean().optional() });
const smsSchema = z.object({ patientId:id.optional(), phone:z.string().trim().min(7).max(40), message:z.string().trim().min(1).max(480), category:z.string().trim().min(2).max(60).default('GENERAL') });
const emergencyTaskSchema = z.object({ patientId:id.optional(), encounterId:id.optional(), assignedToId:id, title:z.string().trim().min(2).max(160), instructions:z.string().max(4000).optional(), priority:z.enum(['LOW','NORMAL','HIGH','CRITICAL']).default('NORMAL'), dueAt:z.string().datetime().optional() });
const claimSchema = z.object({ patientId:id, policyId:id, providerId:id, invoiceId:id.optional(), preauthorizationId:id.optional(), encounterId:id.optional(), serviceFrom:z.string().datetime(), serviceTo:z.string().datetime(), diagnosisCodes:z.array(z.string().max(40)).max(50).optional(), procedureCodes:z.array(z.string().max(40)).max(100).optional(), totalAmount:z.number().nonnegative(), approvedAmount:z.number().nonnegative().optional(), patientResponsibility:z.number().nonnegative().optional(), notes:z.string().max(4000).optional() });

app.get('/api/health', async (_req,res) => {
  try { await prisma.$queryRaw`SELECT 1`; res.json({ ok:true, service:'EasyNet Solution HIS API', database:'connected', time:new Date().toISOString() }); }
  catch { res.status(503).json({ ok:false, service:'EasyNet Solution HIS API', database:'unavailable' }); }
});

app.post('/api/auth/login', loginRateLimit, async (req,res,next) => {
  try {
    const input = loginSchema.parse(req.body);
    const user = await prisma.user.findUnique({ where:{ email:input.email.toLowerCase() } });
    if (!user || !user.isActive || !(await bcrypt.compare(input.password, user.passwordHash))) return res.status(401).json({ message:'Invalid email or password' });
    await prisma.user.update({ where:{id:user.id}, data:{lastLoginAt:new Date()} });
    setAuthCookie(res, signToken(user));
    const safeUser = { id:user.id,email:user.email,firstName:user.firstName,lastName:user.lastName,role:user.role };
    await audit({ ...req, user }, 'LOGIN', 'User', user.id);
    res.json({ user:safeUser, permissions:ROLE_PERMISSIONS[user.role] || [] });
  } catch(e) { next(e); }
});
app.post('/api/auth/logout', requireAuth, async (req,res) => { await audit(req,'LOGOUT','User',req.user.id); clearAuthCookie(res); res.status(204).end(); });
app.get('/api/auth/me', requireAuth, (req,res) => res.json({ user:req.user, permissions:ROLE_PERMISSIONS[req.user.role] || [] }));
app.use('/api', (req,res,next)=>{
  const publicPath=req.path;
  if(publicPath==='/health'||publicPath==='/settings/public'||publicPath.startsWith('/content-pages/public/')||publicPath.startsWith('/billing/webhooks/')) return next();
  return requireAuth(req,res,next);
});

app.get('/api/dashboard', async (req,res,next) => {
  try {
    const {range,timezone,date} = await todayRange();
    
    const [patients, appointments, labTests, prescriptions, inpatients, beds, pendingRadiology, revenue, recent] = await Promise.all([
      prisma.patient.count({ where:{ status:'ACTIVE' } }),
      prisma.appointment.count({ where:{ scheduledAt:range } }),
      prisma.labOrder.count({ where:{ orderedAt:range } }),
      prisma.prescription.count({ where:{ prescribedAt:range } }),
      prisma.admission.count({ where:{ status:{ in:['ADMITTED','TRANSFERRED'] } } }),
      prisma.bed.count({ where:{ status:'AVAILABLE' } }),
      prisma.radiologyOrder.count({ where:{ status:{ in:['ORDERED','IN_PROGRESS'] } } }),
      prisma.payment.aggregate({ where:{ paidAt:range, status:'COMPLETED' }, _sum:{amount:true} }),
      prisma.auditLog.findMany({ take:8, orderBy:{createdAt:'desc'}, include:{user:{select:{firstName:true,lastName:true}}} })
    ]);
    res.json({ stats:{patients,appointments,labTests,prescriptions,inpatients,availableBeds:beds,pendingRadiology,revenue:Number(revenue._sum.amount || 0)}, reporting:{date,timezone}, activity:recent.map(a=>({id:a.id,time:a.createdAt.toISOString(),title:`${a.action} ${a.entity}`,detail:a.user?`${a.user.firstName} ${a.user.lastName}`:'System',tone:'blue'})) });
  } catch(e) { next(e); }
});

app.get('/api/departments', async (_req,res,next) => { try { res.json(await prisma.department.findMany({where:{active:true},orderBy:{name:'asc'}})); } catch(e){next(e)} });
app.get('/api/users/providers', requirePermission('encounters:read'), async (_req,res,next)=>{ try { res.json(await prisma.user.findMany({where:{isActive:true,role:{in:['PHYSICIAN','DERMATOLOGY','EMERGENCY','MATERNITY','SURGERY','NURSE']}},select:{id:true,firstName:true,lastName:true,role:true},orderBy:{firstName:'asc'}})); } catch(e){next(e)} });

app.get('/api/patients', requirePermission('patients:read'), async (req,res,next) => {
  try { const q=String(req.query.q||'').trim(); const patients=await prisma.patient.findMany({where:q?{OR:[{patientNumber:{contains:q,mode:'insensitive'}},{firstName:{contains:q,mode:'insensitive'}},{lastName:{contains:q,mode:'insensitive'}},{phone:{contains:q,mode:'insensitive'}},{nationalId:{contains:q,mode:'insensitive'}}]}:{},include:{department:{select:{name:true}},allergies:{where:{active:true}}},orderBy:{createdAt:'desc'},take:100}); res.json(patients); }
  catch(e){next(e)}
});
app.get('/api/patients/:id', requirePermission('patients:read'), async (req,res,next) => {
  try {
    const patient = await prisma.patient.findUnique({
      where: { id:req.params.id },
      include: {
        department: true, allergies: true,
        encounters: { orderBy:{startedAt:'desc'}, take:20, include:{department:true,provider:{select:{firstName:true,lastName:true}},diagnoses:true} },
        appointments: { orderBy:{scheduledAt:'desc'}, take:20 },
        labOrders: { orderBy:{orderedAt:'desc'}, take:20, include:{results:true} },
        prescriptions: { orderBy:{prescribedAt:'desc'}, take:20, include:{medication:true} },
        admissions: { orderBy:{admittedAt:'desc'}, take:10, include:{ward:true,bed:true} }
      }
    });
    if (!patient) return res.status(404).json({message:'Patient not found'});
    res.json(patient);
  } catch(e) { next(e); }
});

app.post('/api/patients', requirePermission('patients:create'), async (req,res,next) => {
  try { const input=patientSchema.parse(req.body); const patient=await prisma.$transaction(async tx=>tx.patient.create({data:{...input,dateOfBirth:input.dateOfBirth?new Date(input.dateOfBirth):undefined,patientNumber:await nextNumber(tx,'patient','P')} })); await audit(req,'CREATE','Patient',patient.id,{patientNumber:patient.patientNumber}); res.status(201).json(patient); }
  catch(e){next(e)}
});
app.patch('/api/patients/:id', requirePermission('patients:update'), async (req,res,next)=>{try{const input=patientSchema.partial().parse(req.body);const item=await prisma.patient.update({where:{id:req.params.id},data:{...input,dateOfBirth:input.dateOfBirth?new Date(input.dateOfBirth):undefined}});await audit(req,'UPDATE','Patient',item.id);res.json(item);}catch(e){next(e)}});
app.delete('/api/patients/:id', requirePermission('patients:delete'), async(req,res,next)=>{try{const item=await prisma.patient.update({where:{id:req.params.id},data:{status:'INACTIVE'}});await audit(req,'DELETE','Patient',item.id,{mode:'soft-delete'});res.json({deleted:true,softDeleted:true});}catch(e){next(e)}});

app.get('/api/appointments', requirePermission('appointments:read'), async (_req,res,next)=>{try{res.json(await prisma.appointment.findMany({orderBy:{scheduledAt:'asc'},take:200,include:{patient:{select:{id:true,patientNumber:true,firstName:true,lastName:true}},department:{select:{name:true}},provider:{select:{firstName:true,lastName:true}}}}));}catch(e){next(e)}});
app.post('/api/appointments', requirePermission('appointments:create'), async(req,res,next)=>{try{const input=appointmentSchema.parse(req.body);await assertActivePatient(prisma,input.patientId);await assertActiveDepartment(prisma,input.departmentId);if(input.providerId)await assertActiveUser(prisma,input.providerId,PROVIDER_ROLES);const item=await prisma.appointment.create({data:{...input,scheduledAt:new Date(input.scheduledAt)}});await audit(req,'CREATE','Appointment',item.id);res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/appointments/:id', requirePermission('appointments:update'), async(req,res,next)=>{try{const status=z.enum(['SCHEDULED','CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED','NO_SHOW']).parse(req.body.status);const item=await prisma.appointment.update({where:{id:req.params.id},data:{status}});await audit(req,'UPDATE','Appointment',item.id,{status});res.json(item);}catch(e){next(e)}});
app.delete('/api/appointments/:id', requirePermission('appointments:delete'), async(req,res,next)=>{try{const item=await prisma.appointment.update({where:{id:req.params.id},data:{status:'CANCELLED'}});await audit(req,'DELETE','Appointment',item.id,{mode:'cancel'});res.json({deleted:true});}catch(e){next(e)}});

