app.post('/api/encounters', requirePermission('encounters:create'), async(req,res,next)=>{try{const input=encounterSchema.parse(req.body);await assertActivePatient(prisma,input.patientId);await assertActiveDepartment(prisma,input.departmentId);if(input.providerId)await assertActiveUser(prisma,input.providerId,PROVIDER_ROLES);const item=await prisma.$transaction(async tx=>tx.encounter.create({data:{...input,encounterNumber:await nextNumber(tx,'encounter','ENC')}}));await audit(req,'CREATE','Encounter',item.id,{encounterNumber:item.encounterNumber});res.status(201).json(item);}catch(e){next(e)}});
