app.delete('/api/encounters/:id', requirePermission('encounters:delete'), async(req,res,next)=>{try{const item=await prisma.encounter.update({where:{id:req.params.id},data:{status:'CANCELLED',completedAt:new Date()}});await audit(req,'DELETE','Encounter',item.id,{mode:'cancel'});res.json({deleted:true});}catch(e){next(e)}});
app.post('/api/encounters/:id/notes', requirePermission('encounters:update'), async(req,res,next)=>{try{const input=noteSchema.parse(req.body);const encounter=await prisma.encounter.findUnique({where:{id:req.params.id},select:{id:true,status:true}});if(!encounter)return res.status(404).json({message:'Encounter not found'});if(encounter.status==='CANCELLED')return res.status(409).json({message:'Cancelled encounters cannot receive new clinical notes'});const note=await prisma.clinicalNote.create({data:{...input,encounterId:req.params.id,authorId:req.user.id}});await audit(req,'CREATE','ClinicalNote',note.id,{encounterId:req.params.id});res.status(201).json(note);}catch(e){next(e)}});
app.post('/api/encounters/:id/diagnoses', requirePermission('encounters:update'), async(req,res,next)=>{try{const input=diagnosisSchema.parse(req.body);const encounter=await prisma.encounter.findUnique({where:{id:req.params.id},select:{id:true,status:true}});if(!encounter)return res.status(404).json({message:'Encounter not found'});if(encounter.status==='CANCELLED')return res.status(409).json({message:'Cancelled encounters cannot receive new diagnoses'});const diagnosis=await prisma.diagnosis.create({data:{...input,encounterId:req.params.id}});await audit(req,'CREATE','Diagnosis',diagnosis.id,{encounterId:req.params.id});res.status(201).json(diagnosis);}catch(e){next(e)}});
app.post('/api/encounters/:id/vitals', requirePermission('vitals:create'), async(req,res,next)=>{try{const input=vitalsSchema.parse(req.body);const encounter=await prisma.encounter.findUnique({where:{id:req.params.id},select:{patientId:true,status:true}});if(!encounter)return res.status(404).json({message:'Encounter not found'});if(encounter.status==='CANCELLED')return res.status(409).json({message:'Cancelled encounters cannot receive new vital signs'});const vital=await prisma.vitalSign.create({data:{...input,encounterId:req.params.id,patientId:encounter.patientId}});await audit(req,'CREATE','VitalSign',vital.id);res.status(201).json(vital);}catch(e){next(e)}});

