app.get('/api/lab/orders', requirePermission('lab:read'), async(_req,res,next)=>{try{res.json(await prisma.labOrder.findMany({orderBy:{orderedAt:'desc'},take:200,include:{patient:{select:{patientNumber:true,firstName:true,lastName:true}},department:{select:{name:true}},results:true,test:true}}));}catch(e){next(e)}});
app.post('/api/lab/orders', requirePermission('lab:create'), async(req,res,next)=>{try{const input=labOrderSchema.parse(req.body);await assertActivePatient(prisma,input.patientId);await assertActiveDepartment(prisma,input.departmentId);await assertActiveEncounterLink(prisma,input.encounterId,input.patientId,input.departmentId);if(input.testId){const test=await prisma.labTest.findUnique({where:{id:input.testId},select:{active:true}});if(!test)return res.status(404).json({message:'Laboratory test not found'});if(!test.active)return res.status(409).json({message:'Laboratory test is inactive'});}const item=await prisma.$transaction(async tx=>tx.labOrder.create({data:{...input,orderNumber:await nextNumber(tx,'lab','LAB'),orderedById:req.user.id}}));await audit(req,'CREATE','LabOrder',item.id,{orderNumber:item.orderNumber});res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/lab/orders/:id/status', requirePermission('lab:update'), async(req,res,next)=>{try{const status=z.enum(['ORDERED','COLLECTED','PROCESSING','COMPLETED','CANCELLED']).parse(req.body.status);const item=await prisma.labOrder.update({where:{id:req.params.id},data:{status}});await audit(req,'UPDATE','LabOrder',item.id,{status});res.json(item);}catch(e){next(e)}});
app.patch('/api/lab/orders/:id', requirePermission('lab:update'), async(req,res,next)=>{try{const status=z.enum(['ORDERED','COLLECTED','PROCESSING','COMPLETED','CANCELLED']).parse(req.body.status);const item=await prisma.labOrder.update({where:{id:req.params.id},data:{status}});await audit(req,'UPDATE','LabOrder',item.id,{status});res.json(item);}catch(e){next(e)}});
app.delete('/api/lab/orders/:id', requirePermission('lab:delete'), async(req,res,next)=>{try{const item=await prisma.labOrder.update({where:{id:req.params.id},data:{status:'CANCELLED'}});await audit(req,'DELETE','LabOrder',item.id,{mode:'cancel'});res.json({deleted:true});}catch(e){next(e)}});
app.post('/api/lab/orders/:id/results', requirePermission('lab:update'), async(req,res,next)=>{try{const input=labResultSchema.parse(req.body);const result=await prisma.$transaction(async tx=>{const order=await tx.labOrder.findUnique({where:{id:req.params.id},include:{results:{where:{status:'FINAL'},select:{id:true}}}});if(!order)throw Object.assign(new Error('Lab order not found'),{statusCode:404});if(order.status==='CANCELLED')throw Object.assign(new Error('Cancelled laboratory orders cannot receive results'),{statusCode:409});if(order.results.length)throw Object.assign(new Error('A final result already exists; use the approved amendment workflow'),{statusCode:409});const created=await tx.labResult.create({data:{...input,labOrderId:order.id,status:'DRAFT'}});await tx.labOrder.update({where:{id:order.id},data:{status:'PROCESSING'}});return created;});await audit(req,'CREATE','LabResult',result.id,{labOrderId:req.params.id,status:'DRAFT',smsQueued:false});res.status(201).json(result);}catch(e){next(e)}});
app.post('/api/lab/results/:id/finalize', requirePermission('lab:update'), async(req,res,next)=>{try{const result=await prisma.$transaction(async tx=>{const current=await tx.labResult.findUnique({where:{id:req.params.id},include:{labOrder:{include:{patient:true}}}});if(!current)throw Object.assign(new Error('Laboratory result not found'),{statusCode:404});if(current.status!=='DRAFT')throw Object.assign(new Error('Only draft laboratory results can be finalized'),{statusCode:409});const updated=await tx.labResult.update({where:{id:current.id},data:{status:'FINAL',verifiedById:req.user.id,verifiedAt:new Date()}});await tx.labOrder.update({where:{id:current.labOrderId},data:{status:'COMPLETED'}});return {updated,patient:current.labOrder.patient};});let smsQueued=false;if(result.patient?.phone){await prisma.smsMessage.create({data:{patientId:result.patient.id,phone:result.patient.phone,category:'LAB_RESULT',message:`EasyNet HIS: Your ${result.updated.testName} laboratory result is now verified and available. Please contact the hospital for clinical interpretation.`,createdById:req.user.id}});smsQueued=true;}await audit(req,'FINALIZE','LabResult',result.updated.id,{labOrderId:result.updated.labOrderId,smsQueued});res.json(result.updated);}catch(e){next(e)}});

app.get('/api/result-tracking', requireAuth, async(req,res,next)=>{try{const allowed=ROLE_PERMISSIONS[req.user.role]||[];if(!allowed.includes('*')&&!['lab:read','radiology:read','records:read'].some(p=>allowed.includes(p)))return res.status(403).json({message:'Insufficient permissions'});const q=String(req.query.q||'').trim();const patientId=req.query.patientId||undefined;const [labs,rads]=await Promise.all([prisma.labOrder.findMany({where:patientId?{patientId}:q?{OR:[{orderNumber:{contains:q,mode:'insensitive'}},{testName:{contains:q,mode:'insensitive'}},{patient:{OR:[{patientNumber:{contains:q,mode:'insensitive'}},{firstName:{contains:q,mode:'insensitive'}},{lastName:{contains:q,mode:'insensitive'}}]}}]}:undefined,orderBy:{orderedAt:'desc'},take:200,include:{patient:{select:{id:true,patientNumber:true,firstName:true,lastName:true,phone:true}},orderedBy:{select:{id:true,firstName:true,lastName:true,role:true}},results:{orderBy:{createdAt:'desc'},include:{verifiedBy:{select:{id:true,firstName:true,lastName:true,role:true}}}}}}),prisma.radiologyOrder.findMany({where:patientId?{patientId}:q?{OR:[{orderNumber:{contains:q,mode:'insensitive'}},{studyName:{contains:q,mode:'insensitive'}},{patient:{OR:[{patientNumber:{contains:q,mode:'insensitive'}},{firstName:{contains:q,mode:'insensitive'}},{lastName:{contains:q,mode:'insensitive'}}]}}]}:undefined,orderBy:{orderedAt:'desc'},take:200,include:{patient:{select:{id:true,patientNumber:true,firstName:true,lastName:true,phone:true}},department:{select:{name:true}}}})]);const ids=[...labs.map(x=>x.patientId),...rads.map(x=>x.patientId)];const sms=ids.length?await prisma.smsMessage.findMany({where:{patientId:{in:[...new Set(ids)]},category:{in:['LAB_RESULT','RADIOLOGY_RESULT']}},orderBy:{createdAt:'desc'},take:500}):[];const rows=[...labs.map(o=>({id:`lab-${o.id}`,source:'LABORATORY',orderId:o.id,orderNumber:o.orderNumber,patient:o.patient,service:o.testName,orderedAt:o.orderedAt,status:o.status,result:o.results[0]||null,orderedBy:o.orderedBy,events:[{status:'ORDERED',at:o.orderedAt,label:'Order created'},...(o.status!=='ORDERED'?[{status:o.status,at:o.results[0]?.createdAt||o.orderedAt,label:o.status==='COMPLETED'?'Result completed':`Order ${o.status.toLowerCase()}`}]:[]),...(o.results||[]).map(r=>({status:r.status,at:r.verifiedAt||r.createdAt,label:r.status==='FINAL'?'Result verified':'Result entered',by:r.verifiedBy}))],sms:sms.filter(m=>m.patientId===o.patientId&&m.category==='LAB_RESULT')[0]||null})),...rads.map(o=>({id:`rad-${o.id}`,source:'RADIOLOGY',orderId:o.id,orderNumber:o.orderNumber,patient:o.patient,service:`${o.modality} · ${o.studyName}`,orderedAt:o.orderedAt,status:o.status,result:o.reportText?{status:o.status,reportText:o.reportText}:null,orderedBy:null,events:[{status:'ORDERED',at:o.orderedAt,label:'Order created'},...(o.status!=='ORDERED'?[{status:o.status,at:o.updatedAt,label:o.status==='COMPLETED'?'Report completed':`Study ${o.status.toLowerCase()}`}]:[])],sms:sms.filter(m=>m.patientId===o.patientId&&m.category==='RADIOLOGY_RESULT')[0]||null}))].sort((a,b)=>new Date(b.orderedAt)-new Date(a.orderedAt));res.json(rows)}catch(e){next(e)}});

app.get('/api/radiology/orders', requirePermission('radiology:read'), async(_req,res,next)=>{try{res.json(await prisma.radiologyOrder.findMany({orderBy:{orderedAt:'desc'},take:200,include:{patient:{select:{patientNumber:true,firstName:true,lastName:true}},department:{select:{name:true}}}}));}catch(e){next(e)}});
app.post('/api/radiology/orders', requirePermission('radiology:create'), async(req,res,next)=>{try{const input=radiologySchema.parse(req.body);await assertActivePatient(prisma,input.patientId);await assertActiveDepartment(prisma,input.departmentId);await assertActiveEncounterLink(prisma,input.encounterId,input.patientId,input.departmentId);const item=await prisma.$transaction(async tx=>tx.radiologyOrder.create({data:{...input,orderNumber:await nextNumber(tx,'radiology','RAD')}}));await audit(req,'CREATE','RadiologyOrder',item.id);res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/radiology/orders/:id', requirePermission('radiology:update'), async(req,res,next)=>{try{const input=z.object({status:z.enum(['ORDERED','IN_PROGRESS','COMPLETED','CANCELLED']),reportText:z.string().trim().max(10000).optional()}).parse(req.body);const current=await prisma.radiologyOrder.findUnique({where:{id:req.params.id},include:{patient:true}});if(!current)return res.status(404).json({message:'Radiology order not found'});if(input.status==='CANCELLED'&&current.status==='COMPLETED')return res.status(409).json({message:'Completed radiology reports cannot be cancelled'});if(input.status==='COMPLETED'&&!String(input.reportText??current.reportText??'').trim())return res.status(400).json({message:'A radiology report is required before completion'});const item=await prisma.radiologyOrder.update({where:{id:current.id},data:{status:input.status,reportText:input.reportText??undefined}});let smsQueued=false;if(input.status==='COMPLETED'&&item.reportText&&current.patient?.phone){await prisma.smsMessage.create({data:{patientId:item.patientId,phone:current.patient.phone,category:'RADIOLOGY_RESULT',message:`EasyNet HIS: Your radiology report is now available. Please contact the hospital for clinical interpretation.`,createdById:req.user.id}});smsQueued=true;}await audit(req,'UPDATE','RadiologyOrder',item.id,{status:input.status,smsQueued});res.json(item);}catch(e){next(e)}});
app.delete('/api/radiology/orders/:id', requirePermission('radiology:delete'), async(req,res,next)=>{try{const item=await prisma.radiologyOrder.update({where:{id:req.params.id},data:{status:'CANCELLED'}});await audit(req,'DELETE','RadiologyOrder',item.id,{mode:'cancel'});res.json({deleted:true});}catch(e){next(e)}});

