app.post('/api/medications', requirePermission('inventory:create'), async(req,res,next)=>{try{const input=z.object({code:z.string().trim().min(1).max(50),name:z.string().trim().min(1).max(160),genericName:z.string().max(160).optional(),strength:z.string().max(80).optional(),form:z.string().max(80).optional(),stockQty:z.number().int().min(0).default(0),reorderAt:z.number().int().min(0).default(10),active:z.boolean().default(true)}).parse(req.body);const item=await prisma.medication.create({data:input});await audit(req,'CREATE','Medication',item.id);res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/medications/:id', requirePermission('inventory:update'), async(req,res,next)=>{try{const input=z.object({code:z.string().trim().min(1).max(50).optional(),name:z.string().trim().min(1).max(160).optional(),genericName:z.string().max(160).optional(),strength:z.string().max(80).optional(),form:z.string().max(80).optional(),stockQty:z.number().int().min(0).optional(),reorderAt:z.number().int().min(0).optional(),active:z.boolean().optional()}).parse(req.body);const item=await prisma.medication.update({where:{id:req.params.id},data:input});await audit(req,'UPDATE','Medication',item.id);res.json(item);}catch(e){next(e)}});
app.delete('/api/medications/:id', requirePermission('inventory:delete'), async(req,res,next)=>{try{const used=await prisma.prescription.count({where:{medicationId:req.params.id}});if(used) {await prisma.medication.update({where:{id:req.params.id},data:{active:false}});await audit(req,'UPDATE','Medication',req.params.id,{reason:'soft-delete',references:used});return res.json({deleted:true,softDeleted:true});}await prisma.medication.delete({where:{id:req.params.id}});await audit(req,'DELETE','Medication',req.params.id);res.status(204).end();}catch(e){next(e)}});
app.get('/api/blood-units', requirePermission('blood:read'), async(_req,res,next)=>{try{res.json(await prisma.bloodUnit.findMany({orderBy:{collectedAt:'desc'},take:500}));}catch(e){next(e)}});
app.post('/api/blood-units', requirePermission('blood:create'), async(req,res,next)=>{try{const input=z.object({unitNumber:z.string().trim().min(1).max(50),donorName:z.string().trim().min(1).max(160),donorPhone:z.string().trim().max(40).optional(),bloodGroup:z.string().trim().regex(/^(A|B|AB|O)[+-]$/),component:z.enum(['WHOLE_BLOOD','PACKED_RBC','PLASMA','PLATELETS','CRYOPRECIPITATE']).default('WHOLE_BLOOD'),volumeMl:z.number().int().min(1).max(1000).default(450),collectedAt:z.string().datetime(),expiresAt:z.string().datetime(),status:z.enum(['AVAILABLE','RESERVED','ISSUED','QUARANTINED','EXPIRED','DISCARDED']).default('AVAILABLE'),notes:z.string().max(2000).optional()}).parse(req.body);if(new Date(input.expiresAt)<=new Date(input.collectedAt))return res.status(400).json({message:'Expiry must be after collection date'});const item=await prisma.bloodUnit.create({data:{...input,collectedAt:new Date(input.collectedAt),expiresAt:new Date(input.expiresAt)}});await audit(req,'CREATE','BloodUnit',item.id,{unitNumber:item.unitNumber,bloodGroup:item.bloodGroup});res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/blood-units/:id', requirePermission('blood:update'), async(req,res,next)=>{try{const input=z.object({unitNumber:z.string().trim().min(1).max(50).optional(),donorName:z.string().trim().min(1).max(160).optional(),donorPhone:z.string().trim().max(40).optional(),bloodGroup:z.string().trim().regex(/^(A|B|AB|O)[+-]$/).optional(),component:z.enum(['WHOLE_BLOOD','PACKED_RBC','PLASMA','PLATELETS','CRYOPRECIPITATE']).optional(),volumeMl:z.number().int().min(1).max(1000).optional(),collectedAt:z.string().datetime().optional(),expiresAt:z.string().datetime().optional(),status:z.enum(['AVAILABLE','RESERVED','ISSUED','QUARANTINED','EXPIRED','DISCARDED']).optional(),notes:z.string().max(2000).optional()}).parse(req.body);const current=await prisma.bloodUnit.findUnique({where:{id:req.params.id}});if(!current)return res.status(404).json({message:'Blood unit not found'});const collected=input.collectedAt?new Date(input.collectedAt):current.collectedAt;const expires=input.expiresAt?new Date(input.expiresAt):current.expiresAt;if(expires<=collected)return res.status(400).json({message:'Expiry must be after collection date'});const item=await prisma.bloodUnit.update({where:{id:req.params.id},data:{...input,collectedAt:input.collectedAt?collected:undefined,expiresAt:input.expiresAt?expires:undefined}});await audit(req,'UPDATE','BloodUnit',item.id,{status:item.status});res.json(item);}catch(e){next(e)}});
app.delete('/api/blood-units/:id', requirePermission('blood:delete'), async(req,res,next)=>{try{const current=await prisma.bloodUnit.findUnique({where:{id:req.params.id}});if(!current)return res.status(404).json({message:'Blood unit not found'});if(['ISSUED','RESERVED'].includes(current.status))return res.status(409).json({message:'Issued or reserved blood units cannot be deleted'});const item=await prisma.bloodUnit.update({where:{id:current.id},data:{status:'DISCARDED'}});await audit(req,'DELETE','BloodUnit',item.id,{mode:'discard'});res.json({deleted:true,status:item.status});}catch(e){next(e)}});
app.get('/api/prescriptions', requirePermission('prescriptions:read'), async(_req,res,next)=>{try{res.json(await prisma.prescription.findMany({orderBy:{prescribedAt:'desc'},take:200,include:{patient:{select:{patientNumber:true,firstName:true,lastName:true}},medication:true,prescribedBy:{select:{firstName:true,lastName:true}}}}));}catch(e){next(e)}});
app.post('/api/prescriptions', requirePermission('prescriptions:create'), async(req,res,next)=>{try{const input=prescriptionSchema.parse(req.body);await assertActivePatient(prisma,input.patientId);await assertActiveEncounterLink(prisma,input.encounterId,input.patientId);const medication=await prisma.medication.findUnique({where:{id:input.medicationId}});if(!medication?.active)return res.status(400).json({message:'Medication is unavailable'});const item=await prisma.$transaction(async tx=>tx.prescription.create({data:{...input,prescriptionNumber:await nextNumber(tx,'prescription','RX'),prescribedById:req.user.id}}));await audit(req,'CREATE','Prescription',item.id,{prescriptionNumber:item.prescriptionNumber});res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/prescriptions/:id', requirePermission('prescriptions:update'), async(req,res,next)=>{try{const status=z.enum(['ACTIVE','DISPENSED','PARTIALLY_DISPENSED','CANCELLED','EXPIRED']).parse(req.body.status);const current=await prisma.prescription.findUnique({where:{id:req.params.id}});if(!current)return res.status(404).json({message:'Prescription not found'});if(current.status==='DISPENSED'&&status!=='DISPENSED')return res.status(409).json({message:'A dispensed prescription cannot be reopened or cancelled'});const item=await prisma.prescription.update({where:{id:req.params.id},data:{status}});await audit(req,'UPDATE','Prescription',item.id,{status});res.json(item);}catch(e){next(e)}});
app.delete('/api/prescriptions/:id', requirePermission('prescriptions:delete'), async(req,res,next)=>{try{const current=await prisma.prescription.findUnique({where:{id:req.params.id}});if(!current)return res.status(404).json({message:'Prescription not found'});if(current.status==='DISPENSED')return res.status(409).json({message:'Dispensed prescriptions cannot be deleted'});const item=await prisma.prescription.update({where:{id:req.params.id},data:{status:'CANCELLED'}});await audit(req,'DELETE','Prescription',item.id,{mode:'cancel'});res.json({deleted:true});}catch(e){next(e)}});
app.post('/api/prescriptions/:id/dispense', requirePermission('pharmacy:dispense'), async(req,res,next)=>{try{const result=await prisma.$transaction(async tx=>{const rx=await tx.prescription.findUnique({where:{id:req.params.id},include:{medication:true}});if(!rx)throw Object.assign(new Error('Prescription not found'),{statusCode:404});if(rx.status!=='ACTIVE')throw Object.assign(new Error('Prescription is not active'),{statusCode:400});const updated=await tx.medication.updateMany({where:{id:rx.medicationId,stockQty:{gte:rx.quantity}},data:{stockQty:{decrement:rx.quantity}}});if(updated.count!==1)throw Object.assign(new Error('Insufficient medication stock'),{statusCode:409});await tx.stockTransaction.create({data:{medicationId:rx.medicationId,type:'DISPENSE',quantity:-rx.quantity,reference:rx.prescriptionNumber}});return tx.prescription.update({where:{id:rx.id},data:{status:'DISPENSED',dispensedAt:new Date()}});});await audit(req,'DISPENSE','Prescription',result.id);res.json(result);}catch(e){next(e)}});

app.get('/api/vitals', requirePermission('patients:read'), async(_req,res,next)=>{try{const rows=await prisma.vitalSign.findMany({take:300,orderBy:{recordedAt:'desc'},include:{patient:{select:{patientNumber:true,firstName:true,lastName:true}},encounter:{select:{encounterNumber:true}}}});res.json(rows);}catch(e){next(e)}});
app.post('/api/vitals', requirePermission('vitals:create'), async(req,res,next)=>{try{const input=vitalsSchema.extend({patientId:id,encounterId:id.optional()}).parse(req.body);await assertActivePatient(prisma,input.patientId);if(input.encounterId)await assertActiveEncounterLink(prisma,input.encounterId,input.patientId);const {patientId,encounterId,...values}=input;const vital=await prisma.vitalSign.create({data:{...values,patientId,encounterId}});await audit(req,'CREATE','VitalSign',vital.id,{patientId});res.status(201).json(vital);}catch(e){next(e)}});

// OPD queue: check-in creates a linked OPD encounter atomically.
app.get('/api/opd/queue', requirePermission('outpatient:read'), async(req,res,next)=>{try{const where=req.query.status?{status:String(req.query.status)}:{};res.json(await prisma.opdQueueEntry.findMany({where,orderBy:{checkInAt:'asc'},take:300,include:{patient:{select:{patientNumber:true,firstName:true,lastName:true,phone:true}},department:{select:{name:true,code:true}},provider:{select:{firstName:true,lastName:true}},encounter:{select:{encounterNumber:true,status:true}}}}));}catch(e){next(e)}});
app.post('/api/opd/queue', requirePermission('outpatient:create'), async(req,res,next)=>{try{const input=z.object({patientId:id,departmentId:id,providerId:id.optional(),appointmentId:id.optional(),priority:z.enum(['NORMAL','URGENT','STAT']).default('NORMAL'),notes:z.string().max(2000).optional()}).parse(req.body);await assertActivePatient(prisma,input.patientId);await assertActiveDepartment(prisma,input.departmentId);if(input.providerId)await assertActiveUser(prisma,input.providerId,PROVIDER_ROLES);if(input.appointmentId){const appt=await prisma.appointment.findUnique({where:{id:input.appointmentId},select:{id:true,patientId:true,departmentId:true,status:true}});if(!appt)return res.status(404).json({message:'Appointment not found'});if(appt.patientId!==input.patientId||appt.departmentId!==input.departmentId)return res.status(400).json({message:'Appointment does not match the selected patient and department'});if(['CANCELLED','NO_SHOW','COMPLETED'].includes(appt.status))return res.status(409).json({message:'Appointment is not eligible for OPD check-in'});}const item=await prisma.$transaction(async tx=>{const enc=await tx.encounter.create({data:{encounterNumber:await nextNumber(tx,'encounter','ENC'),patientId:input.patientId,departmentId:input.departmentId,providerId:input.providerId,type:'OPD',status:'OPEN'}});return tx.opdQueueEntry.create({data:{...input,queueNumber:await nextNumber(tx,'opdQueue','OPD'),encounterId:enc.id}})});await audit(req,'CHECK_IN','OPDQueue',item.id,{queueNumber:item.queueNumber});res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/opd/queue/:id', requirePermission('outpatient:update'), async(req,res,next)=>{try{const input=z.object({status:z.enum(['WAITING','CALLED','IN_CONSULTATION','COMPLETED','CANCELLED','NO_SHOW']),providerId:id.optional(),priority:z.enum(['NORMAL','URGENT','STAT']).optional(),notes:z.string().max(2000).optional()}).parse(req.body);const current=await prisma.opdQueueEntry.findUnique({where:{id:req.params.id}});if(!current)return res.status(404).json({message:'OPD queue entry not found'});const item=await prisma.$transaction(async tx=>{const q=await tx.opdQueueEntry.update({where:{id:current.id},data:{...input,calledAt:input.status==='CALLED'&&!current.calledAt?new Date():undefined,completedAt:['COMPLETED','CANCELLED','NO_SHOW'].includes(input.status)?new Date():undefined}});if(q.encounterId){const encounterStatus=input.status==='IN_CONSULTATION'?'IN_PROGRESS':input.status==='COMPLETED'?'COMPLETED':input.status==='CANCELLED'?'CANCELLED':undefined;if(encounterStatus)await tx.encounter.update({where:{id:q.encounterId},data:{status:encounterStatus,completedAt:['COMPLETED','CANCELLED'].includes(input.status)?new Date():undefined}})}return q});await audit(req,'UPDATE','OPDQueue',item.id,{status:item.status});res.json(item);}catch(e){next(e)}});
app.delete('/api/opd/queue/:id', requirePermission('outpatient:update'), async(req,res,next)=>{try{const item=await prisma.opdQueueEntry.update({where:{id:req.params.id},data:{status:'CANCELLED',completedAt:new Date()}});await audit(req,'CANCEL','OPDQueue',item.id);res.json({deleted:true});}catch(e){next(e)}});

app.get('/api/ward-transfers', requirePermission('wards:read'), async(_req,res,next)=>{try{res.json(await prisma.wardTransfer.findMany({orderBy:{transferredAt:'desc'},take:200,include:{admission:{include:{patient:{select:{patientNumber:true,firstName:true,lastName:true}},ward:true,bed:true}},fromWard:true,toWard:true,fromBed:true,toBed:true}}));}catch(e){next(e)}});
app.post('/api/ward-transfers', requirePermission('wards:update'), async(req,res,next)=>{try{const input=z.object({admissionId:id,toWardId:id,toBedId:id,reason:z.string().max(2000).optional()}).parse(req.body);const result=await prisma.$transaction(async tx=>{const admission=await tx.admission.findUnique({where:{id:input.admissionId}});if(!admission||!['ADMITTED','TRANSFERRED'].includes(admission.status))throw Object.assign(new Error('Only an active admission can be transferred'),{statusCode:409});if(admission.bedId===input.toBedId)throw Object.assign(new Error('Target bed must be different from the current bed'),{statusCode:400});const target=await tx.bed.findUnique({where:{id:input.toBedId},select:{id:true,wardId:true,status:true}});if(!target||target.wardId!==input.toWardId)throw Object.assign(new Error('Target bed does not belong to selected ward'),{statusCode:400});const claimed=await tx.bed.updateMany({where:{id:input.toBedId,wardId:input.toWardId,status:'AVAILABLE'},data:{status:'OCCUPIED'}});if(claimed.count!==1)throw Object.assign(new Error('Target bed is no longer available'),{statusCode:409});const transfer=await tx.wardTransfer.create({data:{admissionId:admission.id,fromWardId:admission.wardId,fromBedId:admission.bedId,toWardId:input.toWardId,toBedId:input.toBedId,reason:input.reason}});await tx.bed.updateMany({where:{id:admission.bedId,status:'OCCUPIED'},data:{status:'AVAILABLE'}});await tx.admission.update({where:{id:admission.id},data:{wardId:input.toWardId,bedId:input.toBedId,status:'TRANSFERRED'}});return transfer});await audit(req,'TRANSFER','Admission',input.admissionId,{toWardId:input.toWardId,toBedId:input.toBedId});res.status(201).json(result);}catch(e){next(e)}});

app.get('/api/nursing/tasks', requirePermission('nursing:read'), async(_req,res,next)=>{try{res.json(await prisma.nursingTask.findMany({orderBy:{dueAt:'asc'},take:300,include:{patient:{select:{patientNumber:true,firstName:true,lastName:true}},admission:{select:{admissionNumber:true}},assignedTo:{select:{firstName:true,lastName:true}}}}));}catch(e){next(e)}});
app.post('/api/nursing/tasks', requirePermission('nursing:create'), async(req,res,next)=>{try{const input=z.object({patientId:id,admissionId:id.optional(),assignedToId:id.optional(),taskType:z.string().min(2).max(100),priority:z.enum(['NORMAL','URGENT','STAT']).default('NORMAL'),dueAt:z.coerce.date().optional(),notes:z.string().max(4000).optional()}).parse(req.body);await assertActivePatient(prisma,input.patientId);if(input.assignedToId)await assertActiveUser(prisma,input.assignedToId);if(input.admissionId){const admission=await prisma.admission.findUnique({where:{id:input.admissionId},select:{patientId:true,status:true}});if(!admission)return res.status(404).json({message:'Admission not found'});if(admission.patientId!==input.patientId)return res.status(400).json({message:'Admission does not belong to selected patient'});if(!['ADMITTED','TRANSFERRED'].includes(admission.status))return res.status(409).json({message:'Nursing tasks can only be linked to active admissions'});}const item=await prisma.nursingTask.create({data:input});await audit(req,'CREATE','NursingTask',item.id);res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/nursing/tasks/:id', requirePermission('nursing:update'), async(req,res,next)=>{try{const input=z.object({assignedToId:id.optional(),priority:z.enum(['NORMAL','URGENT','STAT']).optional(),status:z.enum(['OPEN','IN_PROGRESS','COMPLETED','CANCELLED']).optional(),dueAt:z.coerce.date().optional(),notes:z.string().max(4000).optional()}).parse(req.body);if(input.assignedToId)await assertActiveUser(prisma,input.assignedToId);const item=await prisma.nursingTask.update({where:{id:req.params.id},data:{...input,completedAt:input.status==='COMPLETED'?new Date():undefined}});await audit(req,'UPDATE','NursingTask',item.id,{status:item.status});res.json(item);}catch(e){next(e)}});
app.delete('/api/nursing/tasks/:id', requirePermission('nursing:update'), async(req,res,next)=>{try{const item=await prisma.nursingTask.update({where:{id:req.params.id},data:{status:'CANCELLED',completedAt:new Date()}});await audit(req,'CANCEL','NursingTask',item.id);res.json({deleted:true});}catch(e){next(e)}});

app.get('/api/wards', requirePermission('admissions:read'), async(_req,res,next)=>{try{res.json(await prisma.ward.findMany({where:{active:true},include:{department:{select:{name:true}},beds:true},orderBy:{name:'asc'}}));}catch(e){next(e)}});
app.get('/api/admissions', requirePermission('admissions:read'), async(_req,res,next)=>{try{res.json(await prisma.admission.findMany({where:{status:{in:['ADMITTED','TRANSFERRED']}},orderBy:{admittedAt:'desc'},include:{patient:{select:{patientNumber:true,firstName:true,lastName:true}},ward:true,bed:true}}));}catch(e){next(e)}});
app.post('/api/admissions', requirePermission('admissions:update'), async(req,res,next)=>{try{const input=z.object({patientId:id,wardId:id,bedId:id,encounterId:id.optional()}).parse(req.body);await assertActivePatient(prisma,input.patientId);const admission=await prisma.$transaction(async tx=>{const ward=await tx.ward.findUnique({where:{id:input.wardId},select:{id:true,active:true}});if(!ward)return Object.assign(new Error('Ward not found'),{statusCode:404});if(!ward.active)throw Object.assign(new Error('Ward is inactive'),{statusCode:409});await assertActiveEncounterLink(tx,input.encounterId,input.patientId);const activeAdmission=await tx.admission.findFirst({where:{patientId:input.patientId,status:{in:['ADMITTED','TRANSFERRED']}},select:{id:true}});if(activeAdmission)throw Object.assign(new Error('Patient already has an active admission'),{statusCode:409});const bed=await tx.bed.findUnique({where:{id:input.bedId},select:{id:true,wardId:true,status:true}});if(!bed||bed.wardId!==input.wardId)throw Object.assign(new Error('Bed does not belong to selected ward'),{statusCode:400});const claimed=await tx.bed.updateMany({where:{id:input.bedId,wardId:input.wardId,status:'AVAILABLE'},data:{status:'OCCUPIED'}});if(claimed.count!==1)throw Object.assign(new Error('Bed is no longer available'),{statusCode:409});return tx.admission.create({data:{...input,admissionNumber:await nextNumber(tx,'admission','ADM')}});});await audit(req,'ADMIT','Admission',admission.id);res.status(201).json(admission);}catch(e){next(e)}});
app.patch('/api/admissions/:id', requirePermission('admissions:update'), async(req,res,next)=>{try{const input=z.object({status:z.enum(['ADMITTED','TRANSFERRED','DISCHARGED','CANCELLED']),dischargeSummary:z.string().max(10000).optional()}).parse(req.body);const current=await prisma.admission.findUnique({where:{id:req.params.id}});if(!current)return res.status(404).json({message:'Admission not found'});const result=await prisma.$transaction(async tx=>{const updated=await tx.admission.update({where:{id:req.params.id},data:{status:input.status,dischargeSummary:input.dischargeSummary,dischargedAt:['DISCHARGED','CANCELLED'].includes(input.status)?new Date():undefined}});if(['DISCHARGED','CANCELLED'].includes(input.status)&&current.status!=='DISCHARGED'&&current.status!=='CANCELLED')await tx.bed.update({where:{id:current.bedId},data:{status:'AVAILABLE'}});return updated;});await audit(req,'UPDATE','Admission',result.id,{status:input.status});res.json(result);}catch(e){next(e)}});
app.delete('/api/admissions/:id', requirePermission('admissions:delete'), async(req,res,next)=>{try{const current=await prisma.admission.findUnique({where:{id:req.params.id}});if(!current)return res.status(404).json({message:'Admission not found'});if(current.status==='ADMITTED'||current.status==='TRANSFERRED')return res.status(409).json({message:'Active admission must be discharged or cancelled before deletion'});await prisma.admission.delete({where:{id:req.params.id}});await audit(req,'DELETE','Admission',req.params.id);res.status(204).end();}catch(e){next(e)}});
app.post('/api/admissions/:id/discharge', requirePermission('admissions:update'), async(req,res,next)=>{try{const input=z.object({dischargeSummary:z.string().max(10000).optional()}).parse(req.body);const result=await prisma.$transaction(async tx=>{const admission=await tx.admission.findUnique({where:{id:req.params.id}});if(!admission||admission.status==='DISCHARGED')throw Object.assign(new Error('Admission is not active'),{statusCode:400});const updated=await tx.admission.update({where:{id:admission.id},data:{status:'DISCHARGED',dischargedAt:new Date(),dischargeSummary:input.dischargeSummary}});await tx.bed.update({where:{id:admission.bedId},data:{status:'AVAILABLE'}});return updated;});await audit(req,'DISCHARGE','Admission',result.id);res.json(result);}catch(e){next(e)}});

app.get('/api/reports/summary', requirePermission('reports:read'), async(req,res,next)=>{try{const timezone=await getFacilityTimezone();const today=localDateString(new Date(),timezone);const validDate=v=>/^\d{4}-\d{2}-\d{2}$/.test(String(v||''));const fromDate=String(req.query.from||today);const toDate=String(req.query.to||fromDate);if(!validDate(fromDate)||!validDate(toDate))return res.status(400).json({message:'Report dates must use YYYY-MM-DD format'});if(fromDate>toDate)return res.status(400).json({message:'Report start date must be before or equal to end date'});const range=facilityRange(fromDate,toDate,timezone);const [patients,encounters,admissions,lab,radiology,rx,payments,invoices]=await Promise.all([prisma.patient.count({where:{createdAt:range}}),prisma.encounter.count({where:{startedAt:range}}),prisma.admission.count({where:{admittedAt:range}}),prisma.labOrder.count({where:{orderedAt:range}}),prisma.radiologyOrder.count({where:{orderedAt:range}}),prisma.prescription.count({where:{prescribedAt:range}}),prisma.payment.aggregate({where:{paidAt:range,status:'COMPLETED'},_sum:{amount:true},_count:{_all:true}}),prisma.invoice.aggregate({where:{issuedAt:range},_sum:{total:true},_count:{_all:true}})]);res.json({from:range.gte.toISOString(),to:range.lt.toISOString(),fromDate,toDate,timezone,patients,encounters,admissions,labOrders:lab,radiologyOrders:radiology,prescriptions:rx,revenue:Number(payments._sum.amount||0),completedPayments:payments._count._all,invoices:invoices._count._all,invoiced:Number(invoices._sum.total||0)});}catch(e){next(e)}});

app.get('/api/billing/invoices/:id/receipt', requirePermission('billing:read'), async(req,res,next)=>{try{const invoice=await prisma.invoice.findUnique({where:{id:req.params.id},include:{patient:{select:{patientNumber:true,firstName:true,middleName:true,lastName:true,phone:true,email:true,address:true}},items:true,payments:{where:{status:'COMPLETED'},orderBy:{paidAt:'desc'},include:{receivedBy:{select:{firstName:true,lastName:true,role:true}}}}}});if(!invoice)return res.status(404).json({message:'Invoice not found'});const site=await prisma.systemSetting.findUnique({where:{singletonKey:'default'}});const paid=invoice.payments.reduce((a,p)=>a+Number(p.amount),0);const latest=invoice.payments[0]||null;const payload={hospital:{legalName:site?.legalName||'EasyNet Solution P.L.C.',displayName:site?.displayName||'EasyNet HIS',tagline:site?.tagline||'Smart Healthcare · Better Tomorrow',logoUrl:site?.logoUrl||null,logoData:site?.logoData||null,address:site?.address||'',city:site?.city||'',region:site?.region||'',country:site?.country||'Ethiopia',phone:site?.phone||'',emergencyPhone:site?.emergencyPhone||'',email:site?.email||'',website:site?.website||'',taxId:site?.taxId||'',licenseNumber:site?.licenseNumber||'',currency:site?.currency||'ETB',timezone:site?.timezone||'Africa/Addis_Ababa',receiptFooter:site?.receiptFooter||'Thank you for choosing our healthcare service.'},invoice:{id:invoice.id,invoiceNumber:invoice.invoiceNumber,status:invoice.status,issuedAt:invoice.issuedAt,subtotal:Number(invoice.subtotal),discount:Number(invoice.discount),total:Number(invoice.total),items:invoice.items.map(i=>({description:i.description,quantity:i.quantity,unitPrice:Number(i.unitPrice),amount:Number(i.amount)})),paid,balance:Math.max(0,Number(invoice.total)-paid)},payment:latest?{id:latest.id,receiptNumber:latest.receiptNumber,amount:Number(latest.amount),method:latest.method,status:latest.status,reference:latest.reference,paidAt:latest.paidAt,receivedBy:latest.receivedBy}:null,patient:invoice.patient};await audit(req,'READ','Invoice',invoice.id,{document:'receipt'});res.json(payload);}catch(e){next(e)}});

