app.post('/api/insurance/preauthorizations', requirePermission('insurance:create'), async(req,res,next)=>{try{const input=preauthSchema.parse(req.body);const policy=await prisma.insurancePolicy.findFirst({where:{id:input.policyId,patientId:input.patientId,providerId:input.providerId,active:true}});if(!policy)return res.status(400).json({message:'Active policy does not match patient and payer'});const item=await prisma.$transaction(async tx=>tx.preauthorization.create({data:{authorizationNumber:await nextNumber(tx,'preauth','PA'),...input,requestedAmount:input.requestedAmount}}));await audit(req,'CREATE','Preauthorization',item.id,{authorizationNumber:item.authorizationNumber});res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/insurance/preauthorizations/:id', requirePermission('insurance:update'), async(req,res,next)=>{try{const input=z.object({status:z.enum(['REQUESTED','APPROVED','PARTIALLY_APPROVED','REJECTED','EXPIRED','CANCELLED']),approvedAmount:z.number().nonnegative().optional(),decisionNote:z.string().max(4000).optional()}).parse(req.body);const current=await prisma.preauthorization.findUnique({where:{id:req.params.id}});if(!current)return res.status(404).json({message:'Preauthorization not found'});if(input.approvedAmount!=null&&input.approvedAmount>Number(current.requestedAmount))return res.status(400).json({message:'Approved amount cannot exceed requested amount'});const item=await prisma.preauthorization.update({where:{id:req.params.id},data:{...input,decidedAt:['APPROVED','PARTIALLY_APPROVED','REJECTED'].includes(input.status)?new Date():undefined}});await audit(req,'UPDATE','Preauthorization',item.id,{status:item.status});res.json(item);}catch(e){next(e)}});

app.get('/api/insurance/claims', requirePermission('insurance:read'), async(req,res,next)=>{try{res.json(await prisma.claim.findMany({orderBy:{serviceFrom:'desc'},include:{patient:{select:{patientNumber:true,firstName:true,lastName:true}},provider:{select:{name:true,scheme:true}},policy:{select:{policyNumber:true,memberNumber:true}},preauthorization:{select:{authorizationNumber:true,status:true}}}}));}catch(e){next(e)}});
app.post('/api/insurance/claims', requirePermission('insurance:create'), async(req,res,next)=>{try{const input=claimSchema.parse(req.body);if(new Date(input.serviceTo)<new Date(input.serviceFrom))return res.status(400).json({message:'Service end cannot be before service start'});const policy=await prisma.insurancePolicy.findFirst({where:{id:input.policyId,patientId:input.patientId,providerId:input.providerId,active:true}});if(!policy)return res.status(400).json({message:'Active policy does not match patient and payer'});if(input.preauthorizationId){const pa=await prisma.preauthorization.findFirst({where:{id:input.preauthorizationId,patientId:input.patientId,policyId:input.policyId,providerId:input.providerId}});if(!pa)return res.status(400).json({message:'Preauthorization does not match the claim'});if(['REJECTED','CANCELLED','EXPIRED'].includes(pa.status))return res.status(400).json({message:'Selected preauthorization is not valid'});}const total=input.totalAmount;const approved=input.approvedAmount;const responsibility=input.patientResponsibility;const item=await prisma.$transaction(async tx=>tx.claim.create({data:{claimNumber:await nextNumber(tx,'claim','CLM'),...input,serviceFrom:new Date(input.serviceFrom),serviceTo:new Date(input.serviceTo),diagnosisCodes:input.diagnosisCodes,procedureCodes:input.procedureCodes,totalAmount:total,approvedAmount:approved,patientResponsibility:responsibility}}));await audit(req,'CREATE','Claim',item.id,{claimNumber:item.claimNumber});res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/insurance/claims/:id', requirePermission('insurance:update'), async(req,res,next)=>{try{const input=z.object({status:z.enum(['DRAFT','PREAUTH_REQUESTED','SUBMITTED','UNDER_REVIEW','APPROVED','PARTIALLY_APPROVED','REJECTED','PAID','RETURNED']),approvedAmount:z.number().nonnegative().optional(),patientResponsibility:z.number().nonnegative().optional(),rejectionReason:z.string().max(2000).optional(),notes:z.string().max(4000).optional()}).parse(req.body);const current=await prisma.claim.findUnique({where:{id:req.params.id}});if(!current)return res.status(404).json({message:'Claim not found'});if(input.approvedAmount!=null&&input.approvedAmount>Number(current.totalAmount))return res.status(400).json({message:'Approved amount cannot exceed claim total'});const terminal=['PAID'];if(terminal.includes(current.status)&&input.status!==current.status)return res.status(409).json({message:'Paid claims cannot be reopened'});const item=await prisma.claim.update({where:{id:req.params.id},data:{...input,submittedAt:input.status==='SUBMITTED'&&!current.submittedAt?new Date():undefined,decidedAt:['APPROVED','PARTIALLY_APPROVED','REJECTED'].includes(input.status)?new Date():undefined,paidAt:input.status==='PAID'?new Date():undefined}});await audit(req,'UPDATE','Claim',item.id,{status:item.status});res.json(item);}catch(e){next(e)}});
app.delete('/api/insurance/claims/:id', requirePermission('insurance:delete'), async(req,res,next)=>{try{const current=await prisma.claim.findUnique({where:{id:req.params.id}});if(!current)return res.status(404).json({message:'Claim not found'});if(!['DRAFT','RETURNED','REJECTED'].includes(current.status))return res.status(409).json({message:'Only draft, returned or rejected claims may be deleted'});await prisma.claim.delete({where:{id:req.params.id}});await audit(req,'DELETE','Claim',req.params.id);res.status(204).end();}catch(e){next(e)}});

app.get('/api/users', requirePermission('users:read'), async(req,res,next)=>{try{res.json(await prisma.user.findMany({select:{id:true,email:true,firstName:true,lastName:true,role:true,isActive:true,lastLoginAt:true,createdAt:true},orderBy:{createdAt:'desc'}}));}catch(e){next(e)}});
app.post('/api/users', requirePermission('users:create'), async(req,res,next)=>{try{const input=userSchema.extend({password:z.string().min(12).max(128)}).parse(req.body);const passwordHash=await bcrypt.hash(input.password,12);const item=await prisma.user.create({data:{email:input.email.toLowerCase(),firstName:input.firstName,lastName:input.lastName,role:input.role,passwordHash,isActive:input.isActive??true},select:{id:true,email:true,firstName:true,lastName:true,role:true,isActive:true,createdAt:true}});await audit(req,'CREATE','User',item.id,{role:item.role});res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/users/:id', requirePermission('users:update'), async(req,res,next)=>{try{const input=userSchema.partial().parse(req.body);const data={...input};if(input.password){data.passwordHash=await bcrypt.hash(input.password,12);delete data.password;}delete data.email;const item=await prisma.user.update({where:{id:req.params.id},data,select:{id:true,email:true,firstName:true,lastName:true,role:true,isActive:true,lastLoginAt:true,createdAt:true}});await audit(req,'UPDATE','User',item.id,{role:item.role});res.json(item);}catch(e){next(e)}});
app.delete('/api/users/:id', requirePermission('users:delete'), async(req,res,next)=>{try{if(req.params.id===req.user.id)return res.status(400).json({message:'You cannot deactivate your own account'});const item=await prisma.user.update({where:{id:req.params.id},data:{isActive:false},select:{id:true,email:true,isActive:true}});await audit(req,'DELETE','User',item.id,{mode:'deactivate'});res.json(item);}catch(e){next(e)}});

app.get('/api/sms', requirePermission('sms:read'), async(req,res,next)=>{try{const rows=await prisma.smsMessage.findMany({take:200,orderBy:{createdAt:'desc'},include:{patient:{select:{patientNumber:true,firstName:true,lastName:true}}}});res.json(rows);}catch(e){next(e)}});
app.post('/api/sms', requirePermission('sms:create'), async(req,res,next)=>{try{const input=smsSchema.parse(req.body);if(input.patientId){const p=await prisma.patient.findUnique({where:{id:input.patientId},select:{phone:true}});if(!p)return res.status(404).json({message:'Patient not found'});if(!p.phone)return res.status(400).json({message:'Selected patient has no phone number'});if(input.phone!==p.phone) return res.status(400).json({message:'Phone number does not match the selected patient'});}const item=await prisma.smsMessage.create({data:{...input,createdById:req.user.id,status:'QUEUED'}});let updated=item;const providerUrl=process.env.SMS_PROVIDER_URL;if(providerUrl){try{await prisma.smsMessage.update({where:{id:item.id},data:{status:'SENDING'}});const r=await fetch(providerUrl,{method:'POST',headers:{'Content-Type':'application/json',...(process.env.SMS_PROVIDER_TOKEN?{'Authorization':`Bearer ${process.env.SMS_PROVIDER_TOKEN}`}:{})},body:JSON.stringify({to:input.phone,message:input.message,category:input.category,clientReference:item.id})});const payload=await r.json().catch(()=>({}));if(!r.ok)throw new Error(payload.message||`SMS provider returned ${r.status}`);updated=await prisma.smsMessage.update({where:{id:item.id},data:{status:'SENT',providerMessageId:payload.messageId||payload.id||undefined,sentAt:new Date()}});}catch(err){updated=await prisma.smsMessage.update({where:{id:item.id},data:{status:'FAILED',errorMessage:err.message}});}}await audit(req,'CREATE','SmsMessage',item.id,{category:input.category,status:updated.status});res.status(201).json(updated);}catch(e){next(e)}});
app.patch('/api/sms/:id', requirePermission('sms:update'), async(req,res,next)=>{try{const input=z.object({status:z.enum(['QUEUED','SENDING','SENT','DELIVERED','FAILED']),providerMessageId:z.string().max(200).optional(),errorMessage:z.string().max(1000).optional()}).parse(req.body);const item=await prisma.smsMessage.update({where:{id:req.params.id},data:{...input,deliveredAt:input.status==='DELIVERED'?new Date():undefined}});await audit(req,'UPDATE','SmsMessage',item.id,{status:item.status});res.json(item);}catch(e){next(e)}});

app.get('/api/emergency-tasks', requirePermission('emergency-tasks:read'), async(req,res,next)=>{try{const where=req.user.role==='EMERGENCY'||req.user.role==='PHYSICIAN'?{OR:[{assignedToId:req.user.id},{createdById:req.user.id}]}:{};res.json(await prisma.emergencyTask.findMany({where,orderBy:[{priority:'desc'},{createdAt:'desc'}],include:{patient:{select:{patientNumber:true,firstName:true,lastName:true}},assignedTo:{select:{firstName:true,lastName:true,role:true}},createdBy:{select:{firstName:true,lastName:true}}}}));}catch(e){next(e)}});
app.get('/api/emergency-doctors', requirePermission('emergency-tasks:read'), async(req,res,next)=>{try{res.json(await prisma.user.findMany({where:{isActive:true,role:{in:['PHYSICIAN','EMERGENCY']}},select:{id:true,firstName:true,lastName:true,role:true},orderBy:{firstName:'asc'}}));}catch(e){next(e)}});
app.post('/api/emergency-tasks', requirePermission('emergency-tasks:create'), async(req,res,next)=>{try{const input=emergencyTaskSchema.parse(req.body);if(input.patientId)await assertActivePatient(prisma,input.patientId);await assertActiveUser(prisma,input.assignedToId,['PHYSICIAN','EMERGENCY']);const item=await prisma.$transaction(async tx=>tx.emergencyTask.create({data:{taskNumber:await nextNumber(tx,'emergency-task','ER-TASK'),...input,createdById:req.user.id,dueAt:input.dueAt?new Date(input.dueAt):undefined}}));await audit(req,'CREATE','EmergencyTask',item.id,{taskNumber:item.taskNumber,priority:item.priority,assignedToId:item.assignedToId});res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/emergency-tasks/:id', requirePermission('emergency-tasks:update'), async(req,res,next)=>{try{const input=z.object({status:z.enum(['OPEN','ACKNOWLEDGED','IN_PROGRESS','COMPLETED','CANCELLED']),priority:z.enum(['LOW','NORMAL','HIGH','CRITICAL']).optional(),instructions:z.string().max(4000).optional()}).parse(req.body);const current=await prisma.emergencyTask.findUnique({where:{id:req.params.id}});if(!current)return res.status(404).json({message:'Emergency task not found'});if(!['assignedToId','createdById'].some(k=>current[k]===req.user.id)&&!['SYSTEM_ADMINISTRATOR','EMERGENCY'].includes(req.user.role))return res.status(403).json({message:'Only the assigned doctor or emergency team can update this task'});const item=await prisma.emergencyTask.update({where:{id:req.params.id},data:{...input,acknowledgedAt:input.status==='ACKNOWLEDGED'&&!current.acknowledgedAt?new Date():current.acknowledgedAt,completedAt:input.status==='COMPLETED'&&!current.completedAt?new Date():current.completedAt}});await audit(req,'UPDATE','EmergencyTask',item.id,{status:item.status});res.json(item);}catch(e){next(e)}});
app.delete('/api/emergency-tasks/:id', requirePermission('emergency-tasks:update'), async(req,res,next)=>{try{await prisma.emergencyTask.update({where:{id:req.params.id},data:{status:'CANCELLED'}});await audit(req,'DELETE','EmergencyTask',req.params.id);res.json({deleted:true});}catch(e){next(e)}});

const invoiceSchema = z.object({ patientId:id, encounterId:id.optional(), description:z.string().trim().min(2).max(240), amount:z.number().positive(), discount:z.number().nonnegative().default(0) }).refine(v=>v.discount<=v.amount,{path:['discount'],message:'Discount cannot exceed invoice amount'});
const paymentRequestSchema = z.object({ invoiceId:id, provider:z.enum(['TELEBIRR','CBE_BIRR','BANK_TRANSFER','CARD']), amount:z.number().positive() });

app.get('/api/billing/invoices', requirePermission('billing:read'), async(req,res,next)=>{try{const q=String(req.query.q||'').trim();const rows=await prisma.invoice.findMany({where:q?{OR:[{invoiceNumber:{contains:q,mode:'insensitive'}},{patient:{patientNumber:{contains:q,mode:'insensitive'}}},{patient:{firstName:{contains:q,mode:'insensitive'}}},{patient:{lastName:{contains:q,mode:'insensitive'}}}]}:{},orderBy:{issuedAt:'desc'},take:200,include:{patient:{select:{id:true,patientNumber:true,firstName:true,lastName:true,phone:true}},items:true,payments:true,paymentRequests:{orderBy:{createdAt:'desc'},take:5}}});res.json(rows.map(x=>{const paid=x.payments.filter(p=>p.status==='COMPLETED').reduce((a,p)=>a+Number(p.amount),0);return {...x,total:Number(x.total),paid,balance:Math.max(0,Number(x.total)-paid)}}));}catch(e){next(e)}});
app.post('/api/billing/invoices', requirePermission('billing:create'), async(req,res,next)=>{try{const input=invoiceSchema.parse(req.body);const p=await prisma.patient.findUnique({where:{id:input.patientId}});if(!p)return res.status(404).json({message:'Patient not found'});const total=Math.max(0,input.amount-input.discount);const item=await prisma.$transaction(async tx=>{const invoice=await tx.invoice.create({data:{invoiceNumber:await nextNumber(tx,'invoice','INV'),patientId:input.patientId,encounterId:input.encounterId||undefined,status:'ISSUED',subtotal:input.amount,discount:input.discount,total,items:{create:{description:input.description,quantity:1,unitPrice:input.amount,amount:input.amount}}},include:{items:true}});return invoice});await audit(req,'CREATE','Invoice',item.id,{total:Number(item.total)});res.status(201).json(item);}catch(e){next(e)}});
app.get('/api/billing/summary', requirePermission('billing:read'), async(req,res,next)=>{try{const [invoices,payments,pending]=await Promise.all([prisma.invoice.aggregate({_count:{_all:true},_sum:{total:true}}),prisma.payment.aggregate({where:{status:'COMPLETED'},_sum:{amount:true}}),prisma.paymentRequest.count({where:{status:'PENDING'}})]);res.json({invoiceCount:invoices._count._all,invoiced:Number(invoices._sum.total||0),paid:Number(payments._sum.amount||0),pendingQr:pending});}catch(e){next(e)}});
app.post('/api/billing/payment-requests', requirePermission('billing:create'), async(req,res,next)=>{try{const input=paymentRequestSchema.parse(req.body);const invoice=await prisma.invoice.findUnique({where:{id:input.invoiceId},include:{payments:true,patient:true}});if(!invoice)return res.status(404).json({message:'Invoice not found'});const paid=invoice.payments.filter(p=>p.status==='COMPLETED').reduce((a,p)=>a+Number(p.amount),0);const balance=Number(invoice.total)-paid;if(input.amount>balance+0.001)return res.status(400).json({message:`Payment exceeds outstanding balance of ETB ${balance.toFixed(2)}`});const requestNumber=await nextNumber(prisma,'payment-request','PAY');const payload={requestNumber,merchantReference:invoice.invoiceNumber,amount:input.amount,currency:'ETB',provider:input.provider,patientReference:invoice.patient.patientNumber};const providerUrls={TELEBIRR:process.env.TELEBIRR_API_URL,CBE_BIRR:process.env.CBE_BIRR_API_URL};let providerReference=null,qrPayload=JSON.stringify(payload),qrImageUrl=null,rawResponse=null;if(providerUrls[input.provider]){const r=await fetch(providerUrls[input.provider],{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});rawResponse=await r.json().catch(()=>({}));if(!r.ok)throw new Error(rawResponse.message||`${input.provider} gateway returned ${r.status}`);providerReference=rawResponse.reference||rawResponse.transactionId||rawResponse.id||null;qrPayload=rawResponse.qrPayload||qrPayload;qrImageUrl=rawResponse.qrImageUrl||rawResponse.qrUrl||null;}if(!qrImageUrl&&process.env.QR_RENDER_URL){qrImageUrl=`${process.env.QR_RENDER_URL}${encodeURIComponent(qrPayload)}`;}const item=await prisma.paymentRequest.create({data:{requestNumber,invoiceId:invoice.id,provider:input.provider,amount:input.amount,currency:'ETB',providerReference,qrPayload,qrImageUrl,expiresAt:new Date(Date.now()+15*60*1000),rawResponse:rawResponse||undefined}});await audit(req,'CREATE','PaymentRequest',item.id,{provider:input.provider,amount:input.amount,invoiceId:invoice.id});res.status(201).json({...item,amount:Number(item.amount),providerConfigured:!!providerUrls[input.provider]});}catch(e){next(e)}});
app.get('/api/billing/payment-requests', requirePermission('billing:read'), async(req,res,next)=>{try{const rows=await prisma.paymentRequest.findMany({orderBy:{createdAt:'desc'},take:200,include:{invoice:{select:{invoiceNumber:true,patient:{select:{patientNumber:true,firstName:true,lastName:true}}}}}});res.json(rows.map(x=>({...x,amount:Number(x.amount)})));}catch(e){next(e)}});

app.post('/api/billing/payment-requests/:id/cancel', requirePermission('billing:update'), async(req,res,next)=>{try{const item=await prisma.paymentRequest.findUnique({where:{id:req.params.id}});if(!item)return res.status(404).json({message:'Payment request not found'});if(item.status!=='PENDING')return res.status(409).json({message:`Payment request is already ${item.status}`});const updated=await prisma.paymentRequest.update({where:{id:item.id},data:{status:'CANCELLED'}});await audit(req,'CANCEL','PaymentRequest',item.id);res.json(updated);}catch(e){next(e)}});

app.get('/api/billing/payment-requests/:id', requirePermission('billing:read'), async(req,res,next)=>{try{const item=await prisma.paymentRequest.findUnique({where:{id:req.params.id},include:{invoice:{select:{invoiceNumber:true,total:true,patient:{select:{patientNumber:true,firstName:true,lastName:true}}}}}});if(!item)return res.status(404).json({message:'Payment request not found'});res.json({...item,amount:Number(item.amount)});}catch(e){next(e)}});
app.post('/api/billing/payment-requests/:id/reconcile', requirePermission('billing:update'), async(req,res,next)=>{try{const item=await prisma.paymentRequest.findUnique({where:{id:req.params.id},include:{invoice:true}});if(!item)return res.status(404).json({message:'Payment request not found'});if(item.status==='CONFIRMED')return res.json(item);const reference=z.string().trim().min(2).max(200).parse(req.body.reference);const result=await prisma.$transaction(async tx=>{const existing=await tx.payment.findFirst({where:{reference,status:'COMPLETED'}});if(existing)throw Object.assign(new Error('This provider transaction reference has already been reconciled'),{statusCode:409,receiptNumber:existing.receiptNumber});const claimed=await tx.paymentRequest.updateMany({where:{id:item.id,status:'PENDING'},data:{status:'CONFIRMED',providerReference:reference,confirmedAt:new Date()}});if(claimed.count!==1)throw Object.assign(new Error('Payment request is no longer pending'),{statusCode:409});const p=await tx.payment.create({data:{receiptNumber:await nextNumber(tx,'receipt','RCT'),invoiceId:item.invoiceId,amount:item.amount,method:'MOBILE_MONEY',status:'COMPLETED',reference,receivedById:req.user.id}});const paid=await tx.payment.aggregate({where:{invoiceId:item.invoiceId,status:'COMPLETED'},_sum:{amount:true}});const total=Number(item.invoice.total),newPaid=Number(paid._sum.amount||0);await tx.invoice.update({where:{id:item.invoiceId},data:{status:newPaid>=total?'PAID':'PARTIALLY_PAID'}});return {payment:p,paymentRequest:await tx.paymentRequest.findUnique({where:{id:item.id}})}});await audit(req,'CONFIRM','PaymentRequest',item.id,{reference,receiptNumber:result.payment.receiptNumber});res.json({...result,payment:{...result.payment,amount:Number(result.payment.amount)}});}catch(e){next(e)}});
app.post('/api/billing/webhooks/:provider', async(req,res,next)=>{try{const provider=String(req.params.provider).toUpperCase();if(!['TELEBIRR','CBE_BIRR'].includes(provider))return res.status(404).json({message:'Unsupported payment provider'});const secret=provider==='TELEBIRR'?process.env.TELEBIRR_WEBHOOK_SECRET:process.env.CBE_BIRR_WEBHOOK_SECRET;if(IS_PROD&&!secret)return res.status(503).json({message:'Webhook verification is not configured for this provider'});if(secret){const supplied=req.get('x-easynet-signature');const expected=crypto.createHmac('sha256',secret).update(JSON.stringify(req.body)).digest('hex');const a=Buffer.from(String(supplied||''));const b=Buffer.from(expected);if(a.length!==b.length||!crypto.timingSafeEqual(a,b))return res.status(401).json({message:'Invalid webhook signature'});}const ref=req.body.reference||req.body.transactionId||req.body.providerReference;const status=String(req.body.status||'').toUpperCase();const pr=ref?await prisma.paymentRequest.findFirst({where:{providerReference:ref}}):null;if(!pr)return res.status(404).json({message:'Payment request not found'});if(['SUCCESS','COMPLETED','PAID','CONFIRMED'].includes(status)){await prisma.$transaction(async tx=>{const claimed=await tx.paymentRequest.updateMany({where:{id:pr.id,status:'PENDING'},data:{status:'CONFIRMED',confirmedAt:new Date(),rawResponse:req.body}});if(claimed.count!==1)return;const receiver=await tx.user.findFirst({where:{role:'SYSTEM_ADMINISTRATOR',isActive:true},select:{id:true}});if(!receiver)throw Object.assign(new Error('No active system administrator is available to receive the payment'),{statusCode:503});const duplicate=await tx.payment.findFirst({where:{reference:ref,status:'COMPLETED'},select:{id:true}});if(duplicate)throw Object.assign(new Error('Payment reference has already been reconciled'),{statusCode:409});await tx.payment.create({data:{receiptNumber:await nextNumber(tx,'receipt','RCT'),invoiceId:pr.invoiceId,amount:pr.amount,method:'MOBILE_MONEY',status:'COMPLETED',reference:ref,receivedById:receiver.id}});const paid=await tx.payment.aggregate({where:{invoiceId:pr.invoiceId,status:'COMPLETED'},_sum:{amount:true}});const inv=await tx.invoice.findUnique({where:{id:pr.invoiceId}});await tx.invoice.update({where:{id:pr.invoiceId},data:{status:Number(paid._sum.amount||0)>=Number(inv.total)?'PAID':'PARTIALLY_PAID'}})});}else if(['FAILED','CANCELLED','EXPIRED'].includes(status)){await prisma.paymentRequest.update({where:{id:pr.id},data:{status,status,rawResponse:req.body}});}res.json({ok:true});}catch(e){next(e)}});

app.get('/api/settings/public', async(_req,res,next)=>{try{const s=await prisma.systemSetting.findUnique({where:{singletonKey:'default'}});if(!s)return res.json({});res.json({legalName:s.legalName,displayName:s.displayName,tagline:s.tagline,logoUrl:s.logoUrl,logoData:s.logoData,address:s.address,city:s.city,region:s.region,country:s.country,phone:s.phone,email:s.email,website:s.website,emergencyPhone:s.emergencyPhone,currency:s.currency,timezone:s.timezone,dateFormat:s.dateFormat,workingHours:s.workingHours,receiptFooter:s.receiptFooter,aboutText:s.aboutText,privacyNotice:s.privacyNotice,termsText:s.termsText,maintenanceMode:s.maintenanceMode});}catch(e){next(e)}});
app.get('/api/settings', requirePermission('settings:read'), async(_req,res,next)=>{try{let s=await prisma.systemSetting.findUnique({where:{singletonKey:'default'}});if(!s)s=await prisma.systemSetting.create({data:{singletonKey:'default'}});res.json(s);}catch(e){next(e)}});
app.patch('/api/settings', requirePermission('settings:update'), async(req,res,next)=>{try{const input=z.object({legalName:z.string().trim().min(2).max(200).optional(),displayName:z.string().trim().min(2).max(120).optional(),tagline:z.string().max(300).optional(),logoUrl:z.string().url().max(1000).nullable().optional(),logoData:z.string().max(2800000).nullable().optional(),faviconUrl:z.string().url().max(1000).nullable().optional(),address:z.string().max(500).nullable().optional(),city:z.string().max(100).nullable().optional(),region:z.string().max(100).nullable().optional(),country:z.string().max(100).optional(),phone:z.string().max(80).nullable().optional(),email:z.string().email().max(254).nullable().optional(),website:z.string().url().max(1000).nullable().optional(),emergencyPhone:z.string().max(80).nullable().optional(),taxId:z.string().max(100).nullable().optional(),licenseNumber:z.string().max(100).nullable().optional(),currency:z.string().max(10).optional(),timezone:z.string().max(80).optional(),dateFormat:z.string().max(30).optional(),workingHours:z.string().max(500).nullable().optional(),receiptFooter:z.string().max(1000).nullable().optional(),privacyNotice:z.string().max(20000).nullable().optional(),termsText:z.string().max(20000).nullable().optional(),aboutText:z.string().max(20000).nullable().optional(),maintenanceMode:z.boolean().optional()}).parse(req.body);if(input.logoData && !/^data:image\/(png|jpeg|jpg|webp|svg\+xml);base64,/.test(input.logoData))return res.status(400).json({message:'Logo must be a PNG, JPEG, WEBP or SVG data URL'});const item=await prisma.systemSetting.upsert({where:{singletonKey:'default'},update:input,create:{singletonKey:'default',...input}});await audit(req,'UPDATE','SystemSetting',item.id,{fields:Object.keys(input)});res.json(item);}catch(e){next(e)}});
app.get('/api/content-pages', requirePermission('settings:read'), async(_req,res,next)=>{try{res.json(await prisma.contentPage.findMany({orderBy:{updatedAt:'desc'}}));}catch(e){next(e)}});
app.post('/api/content-pages', requirePermission('settings:update'), async(req,res,next)=>{try{const input=z.object({slug:z.string().trim().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/).max(120),title:z.string().trim().min(2).max(200),body:z.string().min(1).max(100000),excerpt:z.string().max(1000).optional(),seoTitle:z.string().max(200).optional(),seoDescription:z.string().max(500).optional(),published:z.boolean().optional()}).parse(req.body);const item=await prisma.contentPage.create({data:{...input,createdById:req.user.id,publishedAt:input.published?new Date():undefined}});await audit(req,'CREATE','ContentPage',item.id,{slug:item.slug});res.status(201).json(item);}catch(e){next(e)}});
app.patch('/api/content-pages/:id', requirePermission('settings:update'), async(req,res,next)=>{try{const input=z.object({slug:z.string().trim().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/).max(120).optional(),title:z.string().trim().min(2).max(200).optional(),body:z.string().min(1).max(100000).optional(),excerpt:z.string().max(1000).nullable().optional(),seoTitle:z.string().max(200).nullable().optional(),seoDescription:z.string().max(500).nullable().optional(),published:z.boolean().optional()}).parse(req.body);const item=await prisma.contentPage.update({where:{id:req.params.id},data:{...input,updatedById:req.user.id,publishedAt:input.published===true?new Date():input.published===false?null:undefined}});await audit(req,'UPDATE','ContentPage',item.id,{slug:item.slug});res.json(item);}catch(e){next(e)}});
app.delete('/api/content-pages/:id', requirePermission('settings:update'), async(req,res,next)=>{try{await prisma.contentPage.delete({where:{id:req.params.id}});await audit(req,'DELETE','ContentPage',req.params.id);res.status(204).end();}catch(e){next(e)}});
app.get('/api/content-pages/public/:slug', async(req,res,next)=>{try{const item=await prisma.contentPage.findFirst({where:{slug:req.params.slug,published:true}});if(!item)return res.status(404).json({message:'Content page not found'});res.json({slug:item.slug,title:item.title,body:item.body,excerpt:item.excerpt,seoTitle:item.seoTitle,seoDescription:item.seoDescription,publishedAt:item.publishedAt});}catch(e){next(e)}});

app.get('/api/audit', requirePermission('records:read'), async(req,res,next)=>{try{res.json(await prisma.auditLog.findMany({take:200,orderBy:{createdAt:'desc'},include:{user:{select:{firstName:true,lastName:true,role:true}}}}));}catch(e){next(e)}});

app.use((err, req, res, _next) => {
  console.error(`[${req.requestId}]`, err);
  if (err?.statusCode) return res.status(err.statusCode).json({ message:err.message, requestId:req.requestId });
  if (err instanceof z.ZodError) return res.status(400).json({ message:'Validation failed', errors:err.flatten(), requestId:req.requestId });
  if (err instanceof Prisma.PrismaClientKnownRequestError) return res.status(409).json({ message:'Database constraint or state conflict', requestId:req.requestId });
  res.status(500).json({ message:'Internal server error', requestId:req.requestId });
});

const server = app.listen(PORT, () => console.log(`EasyNet HIS API listening on port ${PORT}`));
async function shutdown(signal) { console.log(`${signal}: shutting down`); server.close(async () => { await prisma.$disconnect(); process.exit(0); }); setTimeout(()=>process.exit(1),10000).unref(); }
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
